function TrackBrain:__init()
    --printInfo("   ~~~~~~~ TrackBrain:__init() ~~~~~~~")
    self.controller = nil

    self.trackData = nil
    self.trackNodeGOs = nil -- Dictionary<int,TrackNodeGO> key:TrackNodeGO.id
    self.cachedVisibleTrackNodeGOIds = {} -- TrackNodeGO.id
    self.trackPesistsInRuntime = nil -- Dictionary<string,TrackPesist>
    self.isReadingTrackDataAsync = true
    self.mapId = ""
end


function TrackBrain:__delete()
    --printInfo("   ~~~~~~~ TrackBrain:__delete() ~~~~~~~")
    self.trackData = nil
    self.trackNodeGOs = nil
    self.cachedVisibleTrackNodeGOIds = nil
    self.trackPesistsInRuntime = nil
    self.mapId = nil
end



function TrackBrain:Awake()
    KTool.SetActive(self.controller.gameObject, true);
    --printInfo("   ~~~~~~~ TrackBrain:Awake() ~~~~~~~")
end



function TrackBrain:Start()
    --printInfo("   ~~~~~~~ TrackBrain:Start(): begin ~~~~~~~")
    KTool.SetActive(self.controller.gameObject, true);

    -- ============================ self ==================================:
    assert( self.trackNodeGoPrefab )

    local idComp = KTool.GetComponent(self.controller.gameObject, typeof(IDComp))
    assert( not isNull(idComp) )
    self.MapId = idComp.id -- int

    -- 确保 trackBrain 下没有任何 go 
    local tfs = self.controller.gameObject.transform:GetComponentsInChildren(typeof(Transform)) -- 包含自己 Array
    local goNum = 0
    for i=0, tfs.Length-1 do 
        if tfs[0] == self.controller.gameObject.transform then 
            printInfo("找到自己")
        else
            goNum = goNum + 1
        end
    end
    assert( goNum == 0 )

    -- --------- 异步加载 trackData 资源, 然后再执行 初始化 -------------
    self.co_1 = cs_coroutine.start(self.PrepareAsync, self)

    --printInfo("   ~~~~~~~ TrackBrain:Start(): end ~~~~~~~")
end


function TrackBrain:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象

    if self.co_1 then
        cs_coroutine.stop(self.co_1)
        self.co_1 = nil
    end

    self.trackData = nil
    self.trackNodeGOs = nil
    self.trackPesistsInRuntime = nil

    self:Delete()
    --printInfo("   ~~~~~~~ TrackBrain:OnDestroy() ~~~~~~~")
end


-- =============================================================== Self -> ================================================================== -- 


-- 需要先异步加载资源后, 在执行后续的 初始化工作
---@return System.Collections.IEnumerator
function TrackBrain:PrepareAsync() 

    self.isReadingTrackDataAsync = true

    local trackDataReader = TrackDataReader.New()
    cs_coroutine.yield_return(trackDataReader.ReadJsonAsync( trackDataReader, self.MapId ))
    self.trackData = trackDataReader.trackData
    trackDataReader:PrintTrackData() -- todo: debug 用, 未来可删

    -- ----------------------
    self:RecreateAllTrackNodeGOs()
    self:Prepare_trackPesistsInRuntime();

    self.isReadingTrackDataAsync = false
end



-- 读取 TrackData 数据, 将数据整理进本地
---@return void
function TrackBrain:RecreateAllTrackNodeGOs() 
    --printInfo( "~~ tpr ~~ TrackBrain:Read() begin " )

    -- ===================== 装配 self.trackNodeGOs =============================
    local trackNodePesistDic = {} -- Dictionary<int,TrackNodePesist> k: trackNodeGO.id
    self.trackNodeGOs = {}

    -- ==================
    --printInfo( "trackPesists num = " .. #self.trackData.trackPesists )
    for i=1, #self.trackData.trackNodePesists do 
        local trackNodePesist = self.trackData.trackNodePesists[i] -- TrackNodePesist

        local newgo = self:CreateNewTrackNodeGoPrefab_Quad( trackNodePesist.pos, trackNodePesist.id )

        assert( isNull(trackNodePesistDic[trackNodePesist.id]) )
        trackNodePesistDic[trackNodePesist.id] = trackNodePesist

        -- 装配一个 trackNodeGO:
        --printInfo("^^^^koko^^^^ trackNodePesist.id = " .. tostring(trackNodePesist.id) )
        self.trackNodeGOs[trackNodePesist.id] = TrackNodeGO.New(trackNodePesist.id, newgo)
    end

    for id,trackNodeGO in pairs(self.trackNodeGOs) do
        
        local othIds = trackNodePesistDic[id].othTrackNodeIDs
        for j=1, #othIds do 
            local othId = othIds[j]
            local othTrackNodeGO = self.trackNodeGOs[othId]
            TrackNodeGO.Connect( trackNodeGO, othTrackNodeGO )
        end
    end

    local trackNodeGOsLen = table.count(self.trackNodeGOs) -- int
    assert( trackNodeGOsLen > 0, "self.trackNodeGOs num = " .. tostring(trackNodeGOsLen) )
        -- debug:
        -- printInfo("========== 打印 self.trackNodeGOs 信息: ")
        -- for i,tng in pairs(self.trackNodeGOs) do 
        --     tng:PrintInfo()
        -- end
    --printInfo( "~~ tpr ~~ TrackBrain:Read() end " )
end




---@return void
function TrackBrain:Prepare_trackPesistsInRuntime() 
    self.trackPesistsInRuntime = {} 

    for i=1, #self.trackData.trackPesists do 
        local e = self.trackData.trackPesists[i] 
        self.trackPesistsInRuntime[e.trackKeyStr] = e
    end
    assert( table.count(self.trackPesistsInRuntime) > 0 )
end



---@param id integer
---@return TrackNodeGO
function TrackBrain:FindTrackNodeGO( id ) 
    local r = self.trackNodeGOs[id];
    assert( not isNull(r), "程序存在漏洞!!!".."  id = " .. id )
    return r
end



---@return void
function TrackBrain:HideAllTrackNodeGOs() 

    for id,trackNodeGO in pairs(self.trackNodeGOs) do
        trackNodeGO:Hide()
    end
end


-- 暂时熄灭所有点亮的 trackNodeGOs, (为了未来能恢复, 需要缓存这些 id)
-- 目前: 播放剧情时用到
function TrackBrain:TmpHideAllVisibleTrackNodeGOs() 
    self.cachedVisibleTrackNodeGOIds = {} -- TrackNodeGO.id
    for id,trackNodeGO in pairs(self.trackNodeGOs) do
        if trackNodeGO:IsVisible() then 
            table.insert( self.cachedVisibleTrackNodeGOIds, id )
            trackNodeGO:Hide()
        end
    end
end

-- 将 TmpHideAllVisibleTrackNodeGOs 中暂时熄灭的 trackNodeGOs 统统恢复
function TrackBrain:RestoreVisibleTrackNodeGOs() 
    for _,id in pairs(self.cachedVisibleTrackNodeGOIds) do 
        local trackNodeGO = self:FindTrackNodeGO(id)
        trackNodeGO:Display()
    end
end



---@param tNode1 TrackNodeGO
---@param tNode2 TrackNodeGO
---@return string
function TrackBrain.GetTrackKeyStr( tNode1, tNode2 ) 
    assert( not isNull(tNode1), "发现 null 值的 trackNode: tNode1" )
    assert( not isNull(tNode2), "发现 null 值的 trackNode: tNode2" )
    assert( tNode1.id ~= tNode2.id )

    local id1 = tNode1.id 
    local id2 = tNode2.id
    local s1 = (id1 >= 0) and tostring(id1) or ("M" .. tostring(-id1)) -- 负号用 'M' 代替
    local s2 = (id2 >= 0) and tostring(id2) or ("M" .. tostring(-id2)) -- 负号用 'M' 代替
    return (id1 < id2) and (s1.."-"..s2) or (s2.."-"..s1)
end




-- ============================================== 计算 运动 ================================================ //

---@param tNode1 TrackNodeGO
---@param tNode2 TrackNodeGO
---@return SimpleTrack.TrackPesist
function TrackBrain:FindTrackPesistInData( tNode1, tNode2 ) 
    local keyStr = TrackBrain.GetTrackKeyStr(tNode1, tNode2) -- 两个 key 的关系是平等的;
    local trackPesist = self.trackPesistsInRuntime[keyStr]
    return trackPesist -- 可能为 nil
end


-- t: 运动方向:[0f->1f]; 但根据 from 和 to 的顺序, 在函数内部 t值 可能会变成 1-t;
---@param from TrackNodeGO
---@param to TrackNodeGO
---@param moveSpeed number
---@param old_t number
---@param isMoveing boolean
---@param tNode2 TrackNodeGO
---@param tNode2 TrackNodeGO
---@return Vector3, number, boolean
function TrackBrain:CalcTrackMovePos( from, to, moveSpeed, old_t, isMoveing ) 

    local trackPesist = self:FindTrackPesistInData( from, to )

    -- 大概率是因为: tracknode 之间连线了, 但是 没有建立对应的 track;
    assert( not isNull(trackPesist) ) 

    -- 更新 t
    old_t = old_t + (moveSpeed * CS.UnityEngine.Time.deltaTime) / trackPesist.totalLength
    isMoveing = (old_t < 1.0)
    old_t = Mathf.Clamp01( old_t )

    local t = (trackPesist.startTrackNodeID == from.id) and old_t or (1.0-old_t) -- 运动方向倒置  float
    t = Mathf.Clamp01( t )

    -- 最简方法, 顺序遍历...  未来可升级为 二分查找...
    local nodes = trackPesist.nodes
    local isFind = false
    local i = 1 -- 1起始的idx
    for j=1, #nodes do 
        if nodes[j].t >= t then 
            isFind = true
            i = j
            break
        end
    end

    if isFind == false then 
        -- 存在精度问题, 比如 0.999 这种, 一律算作 1f;
        return nodes[#nodes].pos, old_t, isMoveing
    end 
    
    if i == 1 then 
        return nodes[1].pos, old_t, isMoveing
    end

    -- 现在 t 在 (nodes[i-1], nodes[i]] 之间;
    return TrackBrain.Remap( nodes[i-1].t, nodes[i].t, nodes[i-1].pos, nodes[i].pos, t ), old_t, isMoveing
end


---@param t1 number
---@param t2 number
---@param s1 Vector3
---@param s2 Vector3
---@param x number
---@return Vector3
function TrackBrain.Remap( t1, t2, s1, s2, x ) 

    return ((x - t1) / (t2 - t1) * (s2 - s1) + s1)
end



-- ============================================== bfs 寻路算法 ================================================ //
-- return: 此路是否通

---@param from TrackNodeGO
---@param to TrackNodeGO
---@return boolean
function TrackBrain:SearchTracks( from, to ) 

    assert( from.id ~= to.id )
    assert( from ~= to )

    for id,trackNodeGO in pairs(self.trackNodeGOs) do
        trackNodeGO.isBFSChecked = false
        trackNodeGO.nextTrackNodeGO = nil
    end

    -- ===== 反向 bfs: 寻找从 to 直到 from 的链表 =====:
    local deque = {} -- List<TrackNodeGO> 模拟 LinkedList<TrackNodeGO>
    table.insert( deque, to) -- add in end
    to.isBFSChecked = true
    local isRoadFree = false -- bool

    while #deque > 0 do -- !!! bfs
        local current = deque[1] -- TrackNodeGO
        table.remove( deque, 1 ) -- remove first

        if current == from then 
            isRoadFree = true
            break
        end

        for oth,j in pairs(current.othTrackNodes) do 
            if oth.isBFSChecked == false then 
                oth.isBFSChecked = true
                oth.nextTrackNodeGO = current
                --deque.AddLast( e );
                table.insert( deque, oth)
            end
        end
    end

    assert( isRoadFree == true )

    return true;
end




---@param pos Vector3 放心,已经在 TrackDataReader 中转化成 Vector3 类型了
---@param id integer
---@return UnityEngine.GameObject
function TrackBrain:CreateNewTrackNodeGoPrefab_Quad( pos, id ) 

    -- todo: trackNodeGO 是迷宫中的固定资源, 好像不需要做成 pool ...
    local newgo = Object.Instantiate(
        self.trackNodeGoPrefab.gameObject, 
        pos, 
        Quaternion.Euler( 90.0,0.0,0.0 ), 
        self.controller.gameObject.transform
    )
    newgo.name = TrackBrain.AllocateTrackNodeGOName(id)

    local renderer = KTool.GetComponent(newgo, typeof(SpriteRenderer))
    local collider = KTool.GetComponent(newgo, typeof(SphereCollider))
    local idComp = KTool.GetComponent(newgo, typeof(IDComp))

    assert( (not isNull(renderer)) and (not isNull(collider)) and (not isNull(idComp)), "prefab 设置存在问题, 请检查 !!!!!" )
    assert( idComp.stringId == "TrackNodeGO" )

    idComp.id = id

    -- 若是自动分配 id 的过度节点, 不要显示, 也不支持玩家点击它:
    if id < 0 then 
        renderer.enabled = false
        collider.enabled = false
    end
    return newgo
end 



---@param id_ integer
---@return string
function TrackBrain.AllocateTrackNodeGOName( id ) 
    local name = (id>=0) and ("trackNode_" .. tostring(id) ) or ("trackNode_N_" .. tostring(-id) ) -- string
    return name
end








return TrackBrain
